  // The same seed gives the same hills every time the program runs.
  Random.noiseSeed(2000);
  for (int x = -300; x < 300; x++) {
    myPen.setPosition(x, Random.noise(x / 100.0) * 200 - 100);
    myPen.down();
  }
  myPen.up();
}

