class Slime extends Sprite {
  int bounces = 0;

  public Slime() {
    this.addCostume("slime", "slimeGreen");
    // Shown as "Slime: bounces", like a sprite's variable in Scratch.
    this.showVariable("bounces", () -> bounces);
  }

  public void run() {
    this.move(4);
    if (this.isTouchingEdge()) {
      bounces++;
      this.turnRight(180);
    }
  }
}

