class MyStage extends Stage {
  int clicks = 0;

  public MyStage() {
    this.showVariable("clicks", () -> clicks);
  }

  public void whenMouseClicked(MouseCode mouseCode) {
    clicks++;
    // The monitor goes away after five clicks.
    if (clicks == 5) {
      this.hideVariable("clicks");
    }
  }
}

