class CustomStage extends Stage {
  public CustomStage() {
    this.addBackdrop("forest", "background");
    this.addBackdrop("sea", "UIbg");
  }

  public void whenBackdropSwitches(String name) {
    if (name.equals("sea")) {
      this.display("Sea");
    } else if (name.equals("forest")) {
      this.display("Team Trees!");
    }
  }
}

