class MyStage extends Stage {
  public MyStage() {
  }

  // The stage hears its own messages too.
  public void whenIReceive(String message) {
    if (message.equals("darker")) {
      Color color = this.getColor();
      this.setColor(color.withHue(color.getHue() + 10));
    }
  }
}

