  myStage.add(two);

  Text three = new Text("Three", 30, -15, 200);
  three.setStyle(TextStyle.BOX);
  three.setBackgroundColor(200, 240, 200);
  myStage.add(three);

  while (true) {
    myStage.waitSeconds(1.2);
    one.goLayersForwards(1);
    myStage.waitSeconds(1.2);
    one.goLayersForwards(1);
    myStage.waitSeconds(1.2);
    one.goLayersBackwards(2);
  }
}

